<?php
require_once dirname(__DIR__) . '/app/bootstrap.php'; require_login(); require_once dirname(__DIR__) . '/app/layout.php';
$rows=$pdo->query("SELECT b.batch_id,b.batch_number,b.expiry_date,b.quantity_on_hand,b.purchase_unit_cost,m.medicine_name,m.medicine_code, DATEDIFF(b.expiry_date,CURRENT_DATE) AS days_left FROM medicine_batches b JOIN medicines m ON m.medicine_id=b.medicine_id ORDER BY b.expiry_date ASC LIMIT 500")->fetchAll();
page_header('Batch inventory','batches'); ?>
<div class="page-toolbar"><p class="muted">Batch-level balances and expiry monitoring. Stock is changed only through receipt and dispensing workflows.</p><a class="btn primary" href="receive.php">＋ Receive stock</a></div>
<div class="panel"><div class="panel-heading"><div><span class="eyebrow">BATCH REGISTER</span><h3>All medicine batches <span class="count"><?= count($rows) ?></span></h3></div></div><div class="table-wrap"><table><thead><tr><th>Medicine</th><th>Batch number</th><th>Expiry</th><th>Days remaining</th><th>Quantity</th><th>Unit cost</th><th>Condition</th></tr></thead><tbody><?php foreach($rows as $r): $expired=(int)$r['days_left']<=0; $near=!$expired && (int)$r['days_left']<=90; ?><tr><td><strong><?= e($r['medicine_name']) ?></strong><small><?= e($r['medicine_code']) ?></small></td><td><?= e($r['batch_number']) ?></td><td><?= e($r['expiry_date']) ?></td><td><?= $expired?'Expired':(int)$r['days_left'].' days' ?></td><td><?= number_format((int)$r['quantity_on_hand']) ?></td><td><?= number_format((float)$r['purchase_unit_cost'],2) ?></td><td><?= $expired?'<span class="pill danger">Expired</span>':($near?'<span class="pill warning">Near expiry</span>':'<span class="pill success">Usable</span>') ?></td></tr><?php endforeach; ?><?php if(!$rows): ?><tr><td colspan="7" class="empty-state">No batches yet. Receive stock to create the first batch.</td></tr><?php endif; ?></tbody></table></div></div>
<?php page_footer(); ?>
